#include "six.hpp"
#include <fstream>
#include <iostream>
#include <iomanip>
#include <chrono>
#include <cmath>
#include <algorithm>
#include <map>
namespace fs=std::filesystem;
struct Metrics {int attempted=0,valid=0,pass=0;double sae=0,sse=0,maximum=0;void add(double e,bool ok){attempted++;if(!ok)return;valid++;sae+=std::abs(e);sse+=e*e;maximum=std::max(maximum,std::abs(e));pass+=std::abs(e)<=six::tick_deg;}void write(std::ostream& f,const std::string& name)const{f<<name<<','<<attempted<<','<<valid<<','<<sae/std::max(1,valid)<<','<<sqrt(sse/std::max(1,valid))<<','<<maximum<<','<<sae/std::max(1,valid)/.01<<','<<sqrt(sse/std::max(1,valid))/.01<<','<<maximum/.01<<','<<pass<<'\n';}};
static six::Config tune(const std::vector<six::Row>& rows,const std::vector<int>& ids,int method){auto configs=six::candidates(method);if(configs.size()==1)return configs[0];double best=1e300;six::Config selected=configs[0];
 for(auto cfg:configs){Metrics m;bool error=false;try{for(int fold=0;fold<5;fold++){std::vector<int> train,test;for(int i:ids)(rows[i].fold==fold?test:train).push_back(i);if(train.empty()||test.empty())continue;auto model=six::fit(rows,train,cfg);for(int i:test){auto p=six::predict(model,rows[i].x,rows[i].time);m.add(p.t-rows[i].t,true);}}}catch(const std::exception&){error=true;}double score=error?1e300:m.maximum/.01+.1*sqrt(m.sse/std::max(1,m.valid))/.01;if(score<best){best=score;selected=cfg;}}
 if(best>=1e299)throw std::runtime_error("All training-only configurations failed");return selected;
}
int wmain(int argc,wchar_t** argv){try{
 if(argc<4||argc>6)throw std::invalid_argument("Usage: six_compare EXPERIMENT IMAGE_ROOT QR_ASSETS [FIRST_METHOD] [LAST_METHOD]");cv::setNumThreads(1);fs::path experiment=argv[1],root=argv[2],assets=argv[3];int first=argc>4?std::stoi(argv[4]):0,last=argc>5?std::stoi(argv[5]):6;auto rows=six::read_rows(experiment/"observations.csv");if(rows.size()!=575)throw std::runtime_error("Expected575 source rows");std::vector<int> all;for(int i=0;i<(int)rows.size();i++)if(rows[i].cohort!="reference"){if(rows[i].status)throw std::runtime_error("Failed measurement must be resolved before fitting");all.push_back(i);}if(all.size()!=571)throw std::runtime_error("Expected571 development rows");auto ref=six::load_frame(experiment/"cache/reference.yml.gz");auto reference=qrwithbar::detail::read_gray(assets/"reference.png");fs::create_directories(experiment/"results/models");
 for(int method=first;method<=last;method++){
  std::ofstream predictions(experiment/("results/predictions_method"+std::to_string(method)+".csv")),metrics(experiment/("results/metrics_method"+std::to_string(method)+".csv")),configlog(experiment/("results/configs_method"+std::to_string(method)+".csv"));predictions<<std::setprecision(17)<<"path,cohort,fold,session_proxy,T_true,T_pred,error_deg,error_ticks,status,known_session,cost,inference_ms,low_quality_line_samples\n";metrics<<std::setprecision(17)<<"split,attempted,valid,MAE_deg,RMSE_deg,max_abs_deg,MAE_ticks,RMSE_ticks,max_ticks,pass_1tick\n";configlog<<"fold,representation,order,alpha,shrink,gamma\n";Metrics total;std::map<std::string,Metrics> cohort;int processed=0;
  for(int fold=0;fold<5;fold++){
   std::vector<int> train,test;for(int i:all)(rows[i].fold==fold?test:train).push_back(i);auto cfg=tune(rows,train,method);auto model=six::fit(rows,train,cfg);six::save_model(model,experiment/("results/models/method"+std::to_string(method)+"_fold"+std::to_string(fold)+".json"));configlog<<fold<<','<<cfg.representation<<','<<cfg.order<<','<<cfg.alpha<<','<<cfg.shrink<<','<<cfg.gamma<<'\n'<<std::flush;
   for(int i:test){auto& row=rows[i];double predicted=std::numeric_limits<double>::quiet_NaN(),cost=0;int status=0,lowQuality=0;bool known=false;auto start=std::chrono::steady_clock::now();try{six::Prediction p;if(method==4){auto frame=six::load_frame(experiment/("cache/frame"+std::to_string(row.index)+".yml.gz"));auto image=qrwithbar::detail::read_gray(root/fs::u8path(row.path));p=six::direct_refine(model,row,frame,ref,image,reference);}else p=six::predict(model,row.x,row.time);predicted=p.t;cost=p.cost;known=p.known_session;lowQuality=p.low_quality_line_samples;}catch(const std::exception& e){status=1;std::cerr<<"Method "<<method<<' '<<row.path<<": "<<e.what()<<'\n';}double ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count(),error=predicted-row.t;total.add(error,status==0);cohort[row.cohort].add(error,status==0);predictions<<row.path<<','<<row.cohort<<','<<fold<<','<<row.session<<','<<row.t<<','<<predicted<<','<<error<<','<<error/.01<<','<<status<<','<<known<<','<<cost<<','<<ms<<','<<lowQuality<<'\n';predictions.flush();processed++;if(processed%50==0)std::cout<<"Method "<<method<<": "<<processed<<"/571\n"<<std::flush;
   }std::cout<<"Method "<<method<<" fold "<<fold<<" completed\n"<<std::flush;
  }
  total.write(metrics,"all");for(auto& c:cohort)c.second.write(metrics,c.first);metrics.flush();auto cfg=tune(rows,all,method);auto model=six::fit(rows,all,cfg);six::save_model(model,experiment/("results/models/deployment_method"+std::to_string(method)+".json"));auto reloaded=six::load_model(experiment/("results/models/deployment_method"+std::to_string(method)+".json"));double roundtrip=0;for(int i:all)roundtrip=std::max(roundtrip,std::abs(six::predict(model,rows[i].x,rows[i].time).t-six::predict(reloaded,rows[i].x,rows[i].time).t));if(roundtrip>1e-10)throw std::runtime_error("Model roundtrip failed");std::cout<<"METHOD "<<method<<" MAE="<<total.sae/total.valid/.01<<" RMSE="<<sqrt(total.sse/total.valid)/.01<<" max="<<total.maximum/.01<<" pass="<<total.pass<<"/571 failures="<<total.attempted-total.valid<<" roundtrip="<<roundtrip<<'\n'<<std::flush;
 }
 return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
